class Kai:
    def __init__(self):
        self.knowledge_graph = KnowledgeGraph()
        self.departments: Dict[Department, BaseDepartment] = {
            Department.PLANNER: Planner(self.knowledge_graph),
            Department.ARCHITECT: Architect(self.knowledge_graph),
            Department.ENGINEER: Engineer(self.knowledge_graph),
            Department.QA: QA(self.knowledge_graph)
        }
        self.task_history: List[Dict[str, Any]] = []
    
    def assign_task(self, task: Dict[str, Any]) -> Dict[str, Any]:
        department = self._determine_responsible_department(task)
        task["status"] = TaskStatus.IN_PROGRESS
        task["assigned_to"] = department.value
        self.task_history.append(task)
        
        result = self.departments[department].process_task(task)
        task["status"] = TaskStatus.COMPLETED
        task["result"] = result
        return task
    
    def _determine_responsible_department(self, task: Dict[str, Any]) -> Department:
        # Simple routing logic based on task type
        if task.get("type") == "planning":
            return Department.PLANNER
        elif task.get("type") == "design":
            return Department.ARCHITECT
        elif task.get("type") == "implementation":
            return Department.ENGINEER
        elif task.get("type") == "validation":
            return Department.QA
        else:
            return Department.PLANNER  # Default
    
    def self_modify(self, modification: Dict[str, Any]) -> None:
        # Example self-modification: Add new department
        if modification.get("action") == "add_department":
            department_type = modification["department_type"]
            department_class = modification["department_class"]
            self.departments[department_type] = department_class(self.knowledge_graph)

