class TestAIWorkforce(unittest.TestCase):
    def setUp(self):
        self.knowledge_graph = KnowledgeGraph()
        self.kai = Kai()
    
    def test_planner_task_decomposition(self):
        task = {"id": "T001", "type": "planning", "description": "Design system architecture"}
        result = self.kai.assign_task(task)
        
        self.assertEqual(result["assigned_to"], Department.PLANNER.value)
        self.assertEqual(result["status"], TaskStatus.COMPLETED)
        self.assertIn("subtasks", result["result"])
        self.assertEqual(len(result["result"]["subtasks"]), 3)
        self.assertEqual(self.kai.knowledge_graph.get(f"planner_{task['id']}"), result["result"])
    
    def test_architect_system_design(self):
        task = {"id": "T002", "type": "design", "description": "Create API architecture"}
        result = self.kai.assign_task(task)
        
        self.assertEqual(result["assigned_to"], Department.ARCHITECT.value)
        self.assertEqual(result["status"], TaskStatus.COMPLETED)
        self.assertEqual(result["result"]["design"], "modular_microservices_architecture")
        self.assertEqual(self.kai.knowledge_graph.get(f"architect_{task['id']}"), result["result"])
    
    def test_engineer_code_generation(self):
        task = {"id": "T003", "type": "implementation", "description": "Generate sample code"}
        result = self.kai.assign_task(task)
        
        self.assertEqual(result["assigned_to"], Department.ENGINEER.value)
        self.assertEqual(result["status"], TaskStatus.COMPLETED)
        self.assertIn("def sample_function()", result["result"]["output"])
        self.assertEqual(self.kai.knowledge_graph.get(f"engineer_{task['id']}"), result["result"])
    
    def test_qa_validation(self):
        task = {"id": "T004", "type": "validation", "description": "Test generated code"}
        result = self.kai.assign_task(task)
        
        self.assertEqual(result["assigned_to"], Department.QA.value)
        self.assertEqual(result["status"], TaskStatus.COMPLETED)
        self.assertEqual(result["result"]["test_results"], "all_tests_passed")
        self.assertEqual(self.kai.knowledge_graph.get(f"qa_{task['id']}"), result["result"])
    
    def test_kai_self_modification(self):
        # Test adding a new department
        class TestDepartment(BaseDepartment):
            def process_task(self, task: Dict[str, Any]) -> Dict[str, Any]:
                return {"action": "test", "status": TaskStatus.COMPLETED}
        
        modification = {
            "action": "add_department",
            "department_type": Department.RESEARCHER,
            "department_class": TestDepartment
        }
        
        self.kai.self_modify(modification)
        self.assertIn(Department.RESEARCHER, self.kai.departments)
        task = {"id": "T005", "type": "research", "description": "Conduct analysis"}
        result = self.kai.assign_task(task)
        self.assertEqual(result["assigned_to"], Department.RESEARCHER.value)

